import math

def solve():
    solutions = []
    for n in range(2, 26):
        is_solution = True
        # We only need to check k from 1 up to n-1, since k=n is congruent to 0 mod n
        for k in range(1, n):
            if math.gcd(k, n) == 1:
                # Check if k^2 === 1 (mod n)
                if (k * k - 1) % n != 0:
                    is_solution = False
                    break

        if is_solution:
            solutions.append(n)

    print("Solutions found for n up to 25:", solutions)

solve()
